async function modeleActif(defaut) {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET',
      url: 'https://jsmffmtzoauvqltshiyg.supabase.co/rest/v1/ia_parametres?id=eq.1&select=modele',
      headers: { apikey: 'sb_publishable_kDVV8tAZEirvMiVXpr4YPw_hmAdT7Mu', Authorization: 'Bearer sb_publishable_kDVV8tAZEirvMiVXpr4YPw_hmAdT7Mu' },
      json: true, timeout: 4000 });
    return (Array.isArray(r) && r[0] && r[0].modele) || defaut;
  } catch (e) { return defaut; }
}

// ===== RÉGLAGES =====
const OLLAMA_URL = 'http://127.0.0.1:11434';     // Ollama sur ton ordinateur (127.0.0.1 plutôt que localhost)
const MODELE = await modeleActif('qwen2.5:7b');  // modèle choisi dans l'onglet "Modèles IA" du pilotage (par défaut : qwen2.5:7b)
const JOURS = 3;                                 // offres publiées ces 3 derniers jours
const MAX_PAR_CLIENT = 15;                       // offres envoyées à l'IA par client
const MAX_PAR_EMAIL = 2;                         // offres au maximum dans un email
const MAX_EMAILS_JOUR = 2;                       // emails au maximum par client et par jour
// =====================
const auj = new Date().toISOString().slice(0, 10);
return [{ json: { OLLAMA_URL, MODELE, JOURS, MAX_PAR_CLIENT, MAX_PAR_EMAIL, MAX_EMAILS_JOUR, debut: new Date().toISOString(),
  depuis: new Date(Date.now() - JOURS * 864e5).toISOString().slice(0, 10),
  il_y_a_30j: new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10),
  il_y_a_180j: new Date(Date.now() - 180 * 864e5).toISOString().slice(0, 10), auj } }];

// Pour chaque client actif : pré-sélection des offres (zone, type, montant, mots-clés, exclusions), puis demande à l'IA.
const R = $('Réglages').first().json;
const clients = $('Lire les clients').all().map(i => i.json).filter(c => c && c.id && c.email);
const offres = $('Lire les offres récentes').all().map(i => i.json).filter(o => o && o.avis_id);
// Offres déjà stockées, plus anciennes, dont la date limite n'est pas passée : servent de rattrapage
const recentes = new Set(offres.map(o => String(o.avis_id)));
const stock = $('Lire les offres encore ouvertes').all().map(i => i.json).filter(o => o && o.avis_id && !recentes.has(String(o.avis_id)));
const envoyees = $('Lire les offres déjà envoyées').all().map(i => i.json).filter(x => x && x.client_id);
const deja = new Set(envoyees.map(x => x.client_id + '|' + x.avis_id));
// Emails déjà envoyés aujourd'hui par client : une heure d'envoi distincte = un email
// (sans la colonne envoye_le, on compte au moins 1 email si des offres sont parties aujourd'hui)
const emailsJour = {};
for (const x of envoyees) {
  if (String(x.date_envoi).slice(0, 10) !== R.auj) continue;
  (emailsJour[x.client_id] ||= new Set()).add(x.envoye_le ? String(x.envoye_le).slice(0, 19) : 'jour');
}
const maxEmails = Number(R.MAX_EMAILS_JOUR) || 2;
let clientsPlafond = 0;
const sans = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const liste = s => String(s || '').split(/[,;]+/).map(x => x.trim()).filter(x => x.length > 2);
// Mots trop généraux (« le marché porte sur… ») : ils feraient passer presque toutes les offres au pré-tri
const TROP_LARGES = new Set(['porte', 'rehabilitation', 'vehicule', 'livraison', 'equipement', 'materiel', 'accompagnement', 'reseaux', 'reseau', 'diagnostic', 'audit', 'revetement', 'conseil', 'travaux', 'services', 'prestations', 'marche', 'entretien', 'maintenance', 'fourniture']);
const dansDeuxJours = Date.now() + 2 * 864e5;
const out = [];
let candidatsTotal = 0;
for (const c of clients) {
  if (c.actif === false) continue;
  if (String(c.formule || 'essai') === 'essai' && c.fin_essai && new Date(c.fin_essai + 'T23:59:59') < new Date()) continue;
  if ((emailsJour[c.id]?.size || 0) >= maxEmails) { clientsPlafond++; continue; }
  const deps = new Set(String(c.departements || '').split(/[,;\s]+/).filter(Boolean).map(d => /^\d$/.test(d) ? '0' + d : d));
  const types = String(c.types || '').toUpperCase().split(/[,;\s]+/).filter(Boolean);
  const mots = [...liste(c.mots_cles), ...liste(c.metiers)].map(sans).filter(m => !TROP_LARGES.has(m));
  const excl = liste(c.exclusions).map(sans);
  const min = Number(c.montant_min) || 0;
  // Avis donnés sur les offres exemples à l'inscription (colonne retours_inscription)
  const retoursC = Array.isArray(c.retours_inscription) ? c.retours_inscription.filter(r => r && r.avis_id) : [];
  const exclues = new Set(retoursC.filter(r => r.avis === 'exclue').map(r => String(r.avis_id)));
  const avisTxt = l => l.map(r => '- ' + String(r.objet || '').slice(0, 160)).join('\n') || '- aucune';
  const exemplesTxt = retoursC.length ? `\nOFFRES JUGÉES PAR L'ENTREPRISE À SON INSCRIPTION (à utiliser comme repères)\nPertinentes :\n${avisTxt(retoursC.filter(r => r.avis === 'pertinente'))}\nÀ exclure :\n${avisTxt(retoursC.filter(r => r.avis === 'exclue'))}\n` : '';
  const garder = o => {
    if (deja.has(c.id + '|' + o.avis_id)) return false;
    if (exclues.has(String(o.avis_id))) return false;
    if (o.limite && new Date(o.limite).getTime() < dansDeuxJours) return false;
    if (deps.size && !(o.departements || []).some(d => deps.has(d))) return false;
    if (types.length && types.length < 3 && !types.some(t => sans(o.type_marche).includes(sans(t)))) return false;
    if (min && o.montant && Number(o.montant) < min) return false;
    const texte = sans(o.objet + ' ' + (o.descripteurs || ''));
    if (excl.some(m => texte.includes(m))) return false;
    if (mots.length && !mots.some(m => texte.includes(m))) return false;
    return true;
  };
  const parDate = (a, b) => String(b.parution).localeCompare(String(a.parution));
  // D'abord les nouvelles offres ; s'il reste de la place, des offres du stock encore ouvertes, jamais envoyées à ce client.
  // L'IA note tout ; « Lire les réponses » n'envoie les offres du stock que si aucune nouvelle offre n'est retenue.
  const nouv = offres.filter(garder).sort(parDate).slice(0, R.MAX_PAR_CLIENT);
  const rattr = stock.filter(garder).sort(parDate).slice(0, R.MAX_PAR_CLIENT - nouv.length).map(o => ({ ...o, stock: true }));
  let cand = [...nouv, ...rattr];
  candidatsTotal += cand.length;
  if (!cand.length) continue;
  const prompt = `Tu aides une PME à repérer les appels d'offres publics qui lui conviennent.

ENTREPRISE
Nom : ${c.entreprise}
Activité : ${c.metiers || 'non précisée'}
Présentation : ${c.description || 'non renseignée'}
Qualifications : ${c.qualifications || 'non renseignées'}
Taille : ${c.effectif || 'effectif non précisé'}, chiffre d'affaires ${c.ca_annuel || 'non précisé'}
Zone : départements ${c.departements || 'non précisés'}
Montant minimum souhaité : ${c.montant_min ? c.montant_min + ' €' : 'aucun'}
Marchés déjà remportés : ${String(c.marches_gagnes || 'inconnus').slice(0, 1200)}
${exemplesTxt}
OFFRES À NOTER (JSON)
${JSON.stringify(cand.map(o => ({ id: o.avis_id, objet: o.objet, acheteur: o.acheteur, lieu: o.lieu, type: o.type_marche, domaines: o.descripteurs, montant: o.montant, duree_mois: o.duree_mois })))}

CONSIGNES (sois ouvert : il vaut mieux proposer une offre de trop qu'en rater une)
- 5 : en plein dans le métier de l'entreprise et à sa taille.
- 4 : dans son métier, même si un détail ne colle pas tout à fait (montant, lieu, durée).
- 3 : en partie dans son métier, par exemple un lot du marché, une prestation proche, ou une sous-traitance possible.
- 2 : lien faible avec son activité.
- 1 : un tout autre métier.
- Un marché découpé en lots mérite au moins 3 si l'un des lots peut correspondre.
- La présentation de l'entreprise donne des exemples, pas une liste fermée : reste large sur les activités voisines.
- Résumé : une phrase simple en français. Pourquoi : une phrase qui explique le lien avec l'entreprise.
- N'invente rien : appuie-toi uniquement sur les informations ci-dessus.
Réponds UNIQUEMENT avec ce JSON : {"offres":[{"id":"...","score":1,"resume":"...","pourquoi":"..."}]}`;
  out.push({ json: { vide: false, client: { id: c.id, email: (c.email_veille && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email_veille)) ? c.email_veille : c.email, entreprise: c.entreprise }, candidats: cand,
    ollama: { model: R.MODELE, stream: false, format: 'json', options: { temperature: 0.1, num_ctx: 16384 },
      messages: [{ role: 'system', content: "Tu es un expert des marchés publics français. Tu réponds toujours en JSON valide, en français." }, { role: 'user', content: prompt }] } } });
}
if (!out.length) return [{ json: { vide: true, clients: clients.length, candidats: 0, clients_plafond: clientsPlafond } }];
out[0].json.stats = { clients: clients.length, candidats: candidatsTotal, clients_plafond: clientsPlafond };
return out;

// Lit la réponse de l'IA pour chaque client : garde les offres notées 3 ou plus, prépare l'email et les lignes à enregistrer.
const prepares = $('Préparer par client').all();
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const fmtL = d => { if (!d) return 'non précisée'; const t = new Date(d); return isNaN(t) ? d : t.toLocaleString('fr-FR', { day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit', timeZone: 'UTC' }); };
const fmtM = n => !n ? 'Montant non communiqué' : n >= 1e6 ? '≈ ' + (n / 1e6).toLocaleString('fr-FR', { maximumFractionDigits: 1 }) + ' M€ HT' : '≈ ' + Math.round(n / 1e3) + ' k€ HT';
const auj = new Date().toISOString().slice(0, 10);
const LOGO = 'https://lumen-marches.pages.dev/logo-signature.png?v=2';
const LOGO_ICONE = 'https://lumen-marches.pages.dev/logo-icone.png?v=2';   // icône seule, pour la signature
const SITE = 'https://lumen-marches.pages.dev/';
const ESPACE = 'https://lumen-marches.pages.dev/tableau.html';

const out = [];
$input.all().forEach((it, i) => {
  const p = prepares[i]?.json; if (!p || p.vide) return;
  let notes = [], erreur = null;
  if (it.json.error) erreur = 'Ollama injoignable ou trop lent : ' + JSON.stringify(it.json.error).slice(0, 200);
  else {
    const txt = it.json.message?.content || it.json.response || '';
    try { const j = JSON.parse(txt); notes = Array.isArray(j) ? j : (j.offres || []); }
    catch (e) { const m = String(txt).match(/\{[\s\S]*\}/); try { notes = JSON.parse(m[0]).offres || []; } catch (e2) { erreur = "Réponse de l'IA illisible"; } }
  }
  const byId = Object.fromEntries(p.candidats.map(o => [String(o.avis_id), o]));
  const retenues = (Array.isArray(notes) ? notes : []).filter(n => Number(n.score) >= 3 && byId[String(n.id)])
    .sort((a, b) => b.score - a.score);
  // Rattrapage : les offres du stock ne partent que si aucune nouvelle offre n'a été retenue
  const nouvelles = retenues.filter(n => !byId[String(n.id)].stock);
  const rattrapage = !nouvelles.length && retenues.length > 0;
  const maxEmail = Number($('Réglages').first().json.MAX_PAR_EMAIL) || 2;
  const garde = (rattrapage ? retenues : nouvelles).slice(0, maxEmail);   // les meilleures notes d'abord
  const lignes = garde.map(n => { const o = byId[String(n.id)]; return { client_id: p.client.id, date_envoi: auj, avis_id: o.avis_id, objet: o.objet.slice(0, 500),
    acheteur: o.acheteur, departement: (o.departements || []).join(', '), lieu: o.lieu, montant: o.montant || null, limite: o.limite || null,
    score: Math.max(1, Math.min(5, Math.round(Number(n.score)))), resume: String(n.resume || '').slice(0, 500), url: o.url }; });

  let html = null, sujet = null;
  if (lignes.length) {
    const pl = lignes.length > 1 ? 's' : '';
    sujet = rattrapage ? `Pas de nouvelle offre ce matin : ${lignes.length} appel${pl} d'offres encore ouvert${pl} pour vous`
      : `${lignes.length} appel${pl} d'offres pour vous ce matin`;

    const prenom = esc(p.client.entreprise);
    const badge = s => s >= 5 ? '#1F7A3F' : s >= 4 ? '#2350C4' : '#8A6D00';
    const badgeBg = s => s >= 5 ? '#E7F6EC' : s >= 4 ? '#EEF2FC' : '#FEF0CC';

    const cartes = garde.map((n, k) => {
      const o = byId[String(n.id)];
      const ligne = lignes[k];
      return `
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F6F7F9;border-radius:10px;margin-bottom:16px;">
        <tr><td style="padding:18px 20px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
            <td style="font-size:15px;font-weight:700;color:#171A21;line-height:1.4;">${esc(o.objet)}</td>
            <td align="right" style="white-space:nowrap;vertical-align:top;padding-left:10px;">
              <span style="display:inline-block;background:${badgeBg(ligne.score)};color:${badge(ligne.score)};font-size:11px;font-weight:700;padding:4px 9px;border-radius:999px;">Pertinence ${ligne.score}/5</span>
            </td>
          </tr></table>
          <p style="margin:6px 0 2px;font-size:13px;color:#6B7280;">${esc(o.acheteur)}${o.lieu ? ', ' + esc(o.lieu) : ''} — réponse avant le ${esc(fmtL(o.limite))}</p>
          <p style="margin:0 0 12px;font-size:13px;color:#8A6D00;font-weight:700;">${esc(fmtM(o.montant))}</p>
          <p style="margin:0 0 10px;font-size:14px;color:#171A21;line-height:1.55;">${esc(n.resume)}</p>
          <table role="presentation" cellpadding="0" cellspacing="0" style="background:#EEF2FC;border-radius:8px;margin-bottom:12px;"><tr><td style="padding:10px 14px;font-size:13px;color:#171A21;line-height:1.5;"><b style="color:#2350C4;">Pourquoi pour vous : </b>${esc(n.pourquoi)}</td></tr></table>
          <a href="${esc(o.url)}" style="font-size:13px;font-weight:700;color:#2350C4;text-decoration:none;">Voir l'avis officiel →</a>
        </td></tr>
      </table>`;
    }).join('');

    html = `<!doctype html>
<html>
<body style="margin:0;padding:0;background:#F6F7F9;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F6F7F9;padding:28px 0;">
<tr><td align="center">
<table role="presentation" width="640" cellpadding="0" cellspacing="0" style="background:#FFFFFF;border-radius:14px;overflow:hidden;border:1px solid #E6E8EC;">

  <tr><td style="padding:22px 32px;border-bottom:1px solid #E6E8EC;">
    <img src="${LOGO}" width="180" height="29" alt="Lumen Marchés" style="display:block;border:0;width:180px;height:29px;">
  </td></tr>

  <tr><td style="padding:28px 32px 6px;">
    <p style="margin:0 0 4px;font-size:12px;font-weight:700;color:#2350C4;text-transform:uppercase;letter-spacing:.04em;">Votre veille du jour</p>
    <p style="margin:0 0 22px;font-size:15px;line-height:1.6;color:#171A21;">${rattrapage
      ? `Bonjour, aucune nouvelle offre correspondant à <b>${prenom}</b> n'a été publiée ces derniers jours. Voici ${lignes.length} appel${pl} d'offres déjà en ligne, toujours ouvert${pl}, que nous ne vous avions pas encore envoyé${pl}.`
      : `Bonjour, voici ${lignes.length} appel${pl} d'offres sélectionné${pl} pour <b>${prenom}</b> ce matin.`}</p>

    ${cartes}

    <table role="presentation" cellpadding="0" cellspacing="0" style="margin:8px 0 24px;">
      <tr><td style="border-radius:8px;background:#2350C4;">
        <a href="${ESPACE}" style="display:inline-block;padding:13px 26px;font-size:14px;font-weight:700;color:#FFFFFF;text-decoration:none;border-radius:8px;">Voir mon espace Lumen</a>
      </td></tr>
    </table>

    <p style="margin:0 0 20px;font-size:13px;color:#6B7280;line-height:1.5;">Retrouvez ces offres, le calendrier des dates limites et l'analyse des dossiers dans votre espace Lumen Marchés.</p>

    <p style="margin:0;font-size:15px;color:#171A21;">Bien cordialement,</p>
  </td></tr>

  <tr><td style="padding:4px 32px 28px;">
    <table role="presentation" cellpadding="0" cellspacing="0" style="border-top:1px solid #E6E8EC;width:100%;">
      <tr>
        <td style="padding-top:18px;vertical-align:middle;width:72px;"><img src="${LOGO_ICONE}" width="40" height="29" alt="Lumen" style="display:block;border:0;width:40px;height:29px;"></td>
        <td style="padding-top:18px;vertical-align:middle;padding-left:14px;border-left:1px solid #E6E8EC;font-size:13px;color:#171A21;line-height:1.5;">
          <b>L'équipe Lumen</b><br>Lumen Marchés<br><a href="${SITE}" style="color:#2350C4;text-decoration:none;">lumen-marches.pages.dev</a>
        </td>
      </tr>
    </table>
  </td></tr>

  <tr><td style="background:#F6F7F9;padding:16px 32px;border-top:1px solid #E6E8EC;">
    <p style="margin:0;font-size:12px;color:#6B7280;">Source : BOAMP. Sélection faite par une IA : vérifiez toujours les dates sur l'avis officiel.</p>
  </td></tr>

</table>
</td></tr>
</table>
</body>
</html>`;
  }
  out.push({ json: { client_id: p.client.id, email: p.client.email, lignes, sujet, html, candidats: p.candidats.length, gardees: lignes.length, rattrapage: rattrapage && lignes.length > 0, erreur } });
});
return out;

// Toutes les offres retenues, pour un seul enregistrement dans Supabase.
const lignes = $input.all().flatMap(i => i.json.lignes || []);
return [{ json: { lignes } }];

const R = $('Réglages').first().json;
const items = $input.all().map(i => i.json);
let statut = 'ok', message = null, entrees = 0, sorties = 0;
const details = { modele: R.MODELE };
if (items.length === 1 && items[0].vide) { statut = 'vide'; entrees = items[0].clients || 0; details.raison = 'aucune offre pré-sélectionnée'; if (items[0].clients_plafond) details.clients_plafond = items[0].clients_plafond; }
else {
  entrees = items.length; sorties = items.reduce((s, x) => s + (x.gardees || 0), 0);
  details.candidats = items.reduce((s, x) => s + (x.candidats || 0), 0);
  details.clients_servis = items.filter(x => x.gardees > 0).length;
  details.clients_rattrapage = items.filter(x => x.rattrapage).length;
  const st0 = $('Préparer par client').first().json.stats; if (st0?.clients_plafond) details.clients_plafond = st0.clients_plafond;
  const err = items.filter(x => x.erreur);
  if (err.length) { details.erreurs = err.length; message = err[0].erreur; if (err.length === items.length) statut = 'erreur'; }
  if (statut === 'ok' && !sorties) statut = 'vide';
}
return [{ json: { agent: 'B-tri', debut: R.debut, fin: new Date().toISOString(), statut, entrees, sorties, details, message } }];
